internal static class AppearanceDescriptions
{
    private static readonly IReadOnlyDictionary<string,string> Help = new Dictionary<string,string>(StringComparer.Ordinal)
    {
        ["card_bg_pattern"] = "Общий рисунок бумаги. Применяется к лицу, обороту с данными и декоративному обороту, если для них не выбран свой вариант. «Чистый» отключает узор, но сохраняет светлоту бумаги.",
        ["card_bg_gray"] = "Общая серость бумаги: 0 — почти белая, 100 — ощутимо светло-серая. Изменяет фон, не цвет текста или рамки; для экономии тонера оставьте 0.",
        ["card_bg_contrast"] = "Насыщенность фонового узора от 0 до 100. Ноль полностью скрывает рисунок. Секреты остаются поверх узора и не меняют цвет.",
        ["front_bg_override"] = "Выделить собственное оформление именно лицевой стороны. Выключено — фон лица наследует общий фон и его серость/контраст.",
        ["front_bg_pattern"] = "Рисунок на лицевой стороне при включённом «Свой фон лица». При выключенном переключателе значение сохраняется, но не применяется.",
